#!/usr/bin/env node
/**
 * Checks the generated brand assets and deep-link files in public/.
 * The assets themselves are generated by `npm run assets` in HunterX-Mobile;
 * this only verifies what was copied here: every file exists, PNGs have the
 * size the metadata promises, and the .well-known files are valid JSON.
 *
 * Usage: npm run assets:verify
 */
import { readFile } from "node:fs/promises";
import path from "node:path";

const PUBLIC_DIR = path.join(process.cwd(), "public");

/** [file, width, height] — must match layout.tsx, seo.ts and site.webmanifest. */
const PNGS = [
  ["favicon-16x16.png", 16, 16],
  ["favicon-32x32.png", 32, 32],
  ["apple-touch-icon.png", 180, 180],
  ["android-chrome-192x192.png", 192, 192],
  ["android-chrome-512x512.png", 512, 512],
  ["maskable-512x512.png", 512, 512],
  ["og-image.png", 1200, 630],
  ["twitter-image.png", 1200, 600],
];

const FILES = ["favicon.ico", "icon.svg", "safari-pinned-tab.svg"];

const JSON_FILES = [
  "site.webmanifest",
  ".well-known/apple-app-site-association",
  ".well-known/assetlinks.json",
];

const PNG_SIGNATURE = Buffer.from([
  0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
]);

const errors = [];
const warnings = [];

async function read(file) {
  try {
    return await readFile(path.join(PUBLIC_DIR, file));
  } catch {
    errors.push(`${file}: missing`);
    return undefined;
  }
}

for (const [file, width, height] of PNGS) {
  const data = await read(file);
  if (!data) continue;
  if (!data.subarray(0, 8).equals(PNG_SIGNATURE)) {
    errors.push(`${file}: not a PNG`);
    continue;
  }
  // IHDR is always the first chunk: width and height at bytes 16-23.
  const actual = [data.readUInt32BE(16), data.readUInt32BE(20)];
  if (actual[0] !== width || actual[1] !== height) {
    errors.push(`${file}: ${actual.join("x")}, expected ${width}x${height}`);
  }
}

for (const file of FILES) await read(file);

for (const file of JSON_FILES) {
  const data = await read(file);
  if (!data) continue;
  try {
    JSON.parse(data.toString("utf8"));
  } catch (error) {
    errors.push(`${file}: invalid JSON (${error.message})`);
    continue;
  }
  const text = data.toString("utf8");
  for (const placeholder of ["TEAMID", "PACKAGE_NAME", "SHA256_FINGERPRINT"]) {
    if (text.includes(placeholder))
      warnings.push(`${file}: still contains ${placeholder}`);
  }
}

for (const warning of warnings) console.warn(`warn  ${warning}`);
for (const error of errors) console.error(`error ${error}`);

if (errors.length > 0) {
  console.error(
    `\n${errors.length} asset problem(s). Regenerate with \`npm run assets\` in HunterX-Mobile.`,
  );
  process.exit(1);
}
console.log(
  `Assets OK (${PNGS.length + FILES.length + JSON_FILES.length} files checked).`,
);
